# 211. 添加与搜索单词 - 数据结构设计
# 设计一个数据结构，支持以下两种操作：
#   - addWord(word): 将单词加入数据结构
#   - search(word): 搜索单词是否存在于数据结构中
# 特殊点: search 中 '.' 可以匹配任意字符（通配符）
#
# 示例:
#   WordDictionary dict = new WordDictionary()
#   dict.addWord("bad"); dict.addWord("dad"); dict.addWord("mad")
#   dict.search("pad") -> False (不存在)
#   dict.search("bad") -> True
#   dict.search(".ad") -> True ('.' 匹配 'b'/'d'/'m')
#   dict.search("b..") -> True
#
# 关键点: Trie 前缀树 + DFS 处理 '.' 通配符
#   - addWord: 沿字符链向下走，不存在就创建节点
#   - search:  遇普通字符直接定位，遇 '.' 递归遍历所有子树

class TrieNode:
    """Trie 节点：children 存子节点映射，is_end 标记单词结束"""
    def __init__(self):
        self.children = {}
        self.is_end = False

class WordDictionary:
    """支持 '.' 通配符搜索的字典树"""
    def __init__(self):
        self.root = TrieNode()
    def addWord(self, word: str) -> None:
        """将 word 插入字典树"""
        node = self.root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
        node.is_end = True
    def search(self, word: str) -> bool:
        """搜索 word；'.' 匹配任意单字符"""
        def dfs(node: TrieNode, i: int) -> bool:
            if i == len(word):
                return node.is_end
            ch = word[i]
            if ch == '.':
                for child in node.children.values():
                    if dfs(child, i + 1):
                        return True
                return False
            if ch not in node.children:
                return False
            return dfs(node.children[ch], i + 1)
        return dfs(self.root, 0)

